describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // fixed 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when mode is not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // same as sum: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // max(0, -50) + max(0, 100) = 0 + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90 → remaining 810
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const bigFirst = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(500), // 500 off 1000 → remaining 500
          new PercentageDiscountPolicy(10), // 10% of 500 = 50
        ],
        "chain",
      );
      const smallFirst = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new FixedAmountDiscountPolicy(500), // 500 off 900 → 500
        ],
        "chain",
      );
      expect(bigFirst.computeDiscountCents(1000)).toBe(550);
      expect(smallFirst.computeDiscountCents(1000)).toBe(600);
    });

    it("stops accumulating when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // takes all 1000
          new FixedAmountDiscountPolicy(500), // remaining is 0, min(500,0)=0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // max(0, -50) = 0, then 100 off 1000 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });
});

