    cart.add(product("a", 100), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(250),
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    expect(result.totals.subtotalCents).toBe(250);
    expect(result.lines[0]!.product.unitPriceCents).toBe(250);
  });

  it("checks inventory and passes when available", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 2);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(200);
    expect(checker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 5);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 10);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 50,
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=100, discounted=900, tax=90, shipping=50
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(90);
    expect(result.totals.shippingCents).toBe(50);
    expect(result.totals.totalCents).toBe(900 + 90 + 50);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price error")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price error",
    );
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 0 };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 100,
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 100), 2);
    cart.add(product("b", 200), 1);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150) // a → 150
        .mockResolvedValueOnce(300), // b → 300
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider,
    });

    // subtotal = 150*2 + 300*1 = 600
    // discount = 0, discounted = 600
    // tax = 5% of 600 = 30
    // shipping = 100
    expect(result.totals.subtotalCents).toBe(600);
    expect(result.totals.taxCents).toBe(30);
    expect(result.totals.shippingCents).toBe(100);
    expect(result.totals.totalCents).toBe(600 + 30 + 100);
    expect(checker.check).toHaveBeenCalledTimes(2);
  });

  it("first inventory denial wins when multiple items fail", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 5);
    cart.add(product("b", 200), 3);
    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a is gone" })
        .mockResolvedValueOnce({ available: false, reason: "b is gone" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("a");
    }
    // Only one check was made (first denial stops)
    expect(checker.check).toHaveBeenCalledTimes(1);
  });

  it("checkout without asyncTaxProvider uses sync tax calculator", async () => {
    const tax: TaxCalculator = {
      computeTaxCents: () => 42,
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.totals.taxCents).toBe(42);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 10000, -50])(
    "returns 0 for subtotal %i",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects invalid percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent (floors)", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0 → 33
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("100% discount equals the subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(9999)).toBe(9999);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(9999)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents %i", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal is larger", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // fixed 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when mode is not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // same as sum: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // max(0, -50) + max(0, 100) = 0 + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90 → remaining 810
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const bigFirst = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(500), // 500 off 1000 → remaining 500
          new PercentageDiscountPolicy(10), // 10% of 500 = 50
        ],
        "chain",
      );
      const smallFirst = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new FixedAmountDiscountPolicy(500), // 500 off 900 → 500
        ],
        "chain",
      );
      expect(bigFirst.computeDiscountCents(1000)).toBe(550);
      expect(smallFirst.computeDiscountCents(1000)).toBe(600);
    });

    it("stops accumulating when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000), // takes all 1000
          new FixedAmountDiscountPolicy(500), // remaining is 0, min(500,0)=0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // max(0, -50) = 0, then 100 off 1000 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });
});

