    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 3000);
      expect(calc.computeShippingCents([line("a", 200)], 3000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 3000);
      expect(calc.computeShippingCents([line("a", 200)], 5000)).toBe(0);
    });

    it("returns flat cost when subtotal is below free-over threshold", () => {
