describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 1.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            1.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 300 },
        { upToGrams: 500, costCents: 200 },
        { upToGrams: 2000, costCents: 500 },
      ],
      800,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(calc.computeShippingCents([noWeightLine("a")], 1000)).toBe(0);
    });

    it("selects the correct bracket for weight at boundary", () => {
      // 500g exactly → first bracket (sorted: 500→200)
      expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(200);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → next bracket (1000→300)
      expect(calc.computeShippingCents([line("a", 501)], 1000)).toBe(300);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g exactly → bracket 2000→500
      expect(calc.computeShippingCents([line("a", 2000)], 1000)).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 2001g → overflow = 800
      expect(calc.computeShippingCents([line("a", 2001)], 1000)).toBe(800);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 200 },
        { upToGrams: 1000, costCents: 400 },
      ]);
      // 5000g → no overflow → heaviest bracket cost = 400
      expect(noOverflow.computeShippingCents([line("a", 5000)], 1000)).toBe(400);
    });

    it("accumulates weight across multiple lines", () => {
      // 2 × 300g = 600g → bracket (1000→300)
      expect(
        calc.computeShippingCents([line("a", 300, 2)], 1000),
      ).toBe(300);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 500 },
        { upToGrams: 500, costCents: 200 },
        { upToGrams: 1000, costCents: 300 },
      ]);
      expect(unsorted.computeShippingCents([line("a", 400)], 1000)).toBe(200);
      expect(unsorted.computeShippingCents([line("a", 700)], 1000)).toBe(300);
      expect(unsorted.computeShippingCents([line("a", 1500)], 1000)).toBe(500);
    });
  });
});

