import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

// ── Cart line management ──────────────────────────────────────────────

describe("Cart line management", () => {
  it("adds a product and reports correct itemCount", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when the same product is added twice", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 2);
    cart.add(product("a", 100), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for product not in cart", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 1)).toThrow(
      "Product missing is not in the cart",
    );
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    cart.add(product("b", 200), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    const p = product("a", 100);
    cart.add(p, 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 1;
    // cart is unaffected
    expect(cart.itemCount).toBe(2);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(100);
  });
});

// ── Cart.totals() pricing pipeline ─────────────────────────────────────

describe("Cart.totals() pricing pipeline", () => {
  it("empty cart yields all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("subtotal sums price × quantity across lines", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 2);
    cart.add(product("b", 300), 1);
    expect(cart.totals().subtotalCents).toBe(500);
  });

  it("applies discount then taxes on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const tax: TaxCalculator = {
      computeTaxCents: (taxable) => Math.floor(taxable * 0.1),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
    });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(200);
    // tax on 800 (discounted) = 80
    expect(t.taxCents).toBe(80);
    expect(t.totalCents).toBe(800 + 80);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 9999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(product("a", 500), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(500); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(product("a", 500), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax: TaxCalculator = {
      computeTaxCents: () => -50,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(product("a", 500), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(product("a", 500), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("shipping receives discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 300,
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: (_lines, subtotalCents) => {
        // free if discounted subtotal >= 500
        return subtotalCents >= 500 ? 0 : 999;
      },
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    // subtotal=1000, discount=300, discountedSubtotal=700 → ≥500 → free
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const tax: TaxCalculator = { computeTaxCents: () => 50 };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 200,
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.totalCents).toBe(1000 - 100 + 50 + 200);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping when no config", () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("region defaults to US", () => {
    let capturedRegion = "";
    const tax: TaxCalculator = {
      computeTaxCents: (_taxable, region) => {
        capturedRegion = region;
        return 0;
      },
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 100), 1);
    cart.totals();
    expect(capturedRegion).toBe("US");
  });

  it("uses configured region", () => {
    let capturedRegion = "";
    const tax: TaxCalculator = {
      computeTaxCents: (_taxable, region) => {
        capturedRegion = region;
        return 0;
      },
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product("a", 100), 1);
    cart.totals();
    expect(capturedRegion).toBe("FR");
  });
});

// ── Cart.checkout() ────────────────────────────────────────────────────

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const result = await cart.checkout();
