      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 10);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 50,
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=100, discounted=900, tax=90, shipping=50
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(90);
    expect(result.totals.shippingCents).toBe(50);
    expect(result.totals.totalCents).toBe(900 + 90 + 50);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price error")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price error",
    );
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 0 };
    const shipping: ShippingCalculator = {
